<?php
namespace App\Services; use App\Core\Database; final class TaxService { public function profile(int $clientId):?array{$s=Database::pdo()->prepare('SELECT * FROM tax_profiles WHERE client_id=?');$s->execute([$clientId]);$r=$s->fetch();return $r?:null;} public function totals(int $clientId,string $year):array{$s=Database::pdo()->prepare('SELECT COALESCE(SUM(amount),0) FROM tax_income WHERE client_id=? AND tax_year=?');$s->execute([$clientId,$year]);$income=(float)$s->fetchColumn();$d=Database::pdo()->prepare('SELECT COALESCE(SUM(amount),0) FROM tax_deductions WHERE client_id=? AND tax_year=?');$d->execute([$clientId,$year]);$ded=(float)$d->fetchColumn();return ['income'=>$income,'deductions'=>$ded,'net'=>$income-$ded];}}
